scwin.vScrenID = "ULDSTF05904.xml";
scwin.clickBzProcsNo = "";
scwin.readOnlyYn = "Y";
scwin.lodingYn = "N";
scwin.pValue = "";
scwin.pfirstValue = "";
scwin.vCond = "";
scwin.rptHeader = "";
scwin.rex_rptname = ""; //Rexpert리포트 파일명 
scwin.userParam;
scwin.testDateSet;
scwin.gComNm = "";
scwin.gCreatDdtm = "";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_set_code = function() {
    dts_ElwInst.DataID = "/CodeAction.do?method=listWrntCd&For=C";
    dts_ElwInst.Reset();
    cmb_ISUR_CD.setSelectedIndex(1); //디폴트값 설정
    //alert("call");

};
scwin.fn_sTimer = function() {
    var clientnow = new Date();
    var curYear = clientnow.getYear();
    var curMonth = (clientnow.getMonth()) + 1;
    var curDay = clientnow.getDate();
    var hours = clientnow.getHours();
    var minutes = clientnow.getMinutes();
    var seconds = clientnow.getSeconds();
    if (minutes <= 9) {
        minutes = "0" + minutes;
    }
    if (seconds <= 9) {
        seconds = "0" + seconds;
    }
    scwin.gCreatDdtm = curYear + "" + curMonth + "" + curDay + "" + hours + "" + minutes + "" + seconds;
    return scwin.gCreatDdtm;
};
scwin.fn_getListBzTpCd = function() {
    var vLIST_BZ_TP_CD;
    var vReportCd = $c.stf.getObjectValue(cmb_REPORT_CD);
    if (MaxTab_01.getSelectedTabIndex() == 1) {
        vLIST_BZ_TP_CD = LIST_BZ_TP_CD_002;
        if (vReportCd == "4" || vReportCd == "5") {
            vLIST_BZ_TP_CD = LIST_BZ_TP_CD_003;
        }
    } else if (MaxTab_01.getSelectedTabIndex() == 2) {
        vLIST_BZ_TP_CD = LIST_BZ_TP_CD_004;
        if (vReportCd == "4" || vReportCd == "5") {
            vLIST_BZ_TP_CD = LIST_BZ_TP_CD_005;
        }
    }
    return vLIST_BZ_TP_CD;
};
scwin.fn_setComNm = function(pIsurCd) {
    var url = "/listingCommon.do?method=listGeneral&outputMessageId=ELW_REPORT_COM_NM_OUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.select.elw.corp.comnm.report.condition" + "&{P}param01=" + pIsurCd;
    dts_ComNm.DataID = encodeURI(url);
    dts_ComNm.reset();
    scwin.gComNm = dts_ComNm.getCellData(1, "COM_NM");
};


/**
 * 인쇄할 내용을 불러온다.
 */
scwin.fn_read_sync = function() {
    var url = "/ElwListedReceive.do?method=reportElwInvstgResult&inputMessageId=ELW_RESULT_REPORT_SEARCH_OUT";
    url += "&REPORT_KND=" + MaxTab_01.getSelectedTabIndex();
    url += "&REPORT_CD=" + $c.stf.getObjectValue(cmb_REPORT_CD);
    url += "&EMP_NO=" + js_emp_no;
    url += "&DATA_CREAT_DDTM=" + scwin.gCreatDdtm;
    url += "&INVSTG_BILL_DD=" + $c.stf.getObjectValue(edt_INVSTG_BILL_DD);
    url += scwin.vCond;
    dts_Report.DataID = encodeURI(url);
    dts_Report.Reset();
};

/**
 * 발행인개황 
 */
scwin.fn_corp_read_sync = function() {
    var url = "/ElwListedReceive.do?method=reportElwCorpDtl&inputMessageId=ELW_RESULT_REPORT_SEARCH_OUT";
    url += "&BZ_PROCS_NO=" + scwin.pfirstValue;
    url += "&REPORT_KND=" + MaxTab_01.getSelectedTabIndex();
    url += "&REPORT_CD=" + $c.stf.getObjectValue(cmb_REPORT_CD);
    dts_CorpReport.DataID = encodeURI(url);
    dts_CorpReport.Reset();
};
scwin.fn_getIsuNmInfo = function(dtsObj) {
    var arrPar = new Array();
    for (var i = 1, p = 0; i <= dtsObj.getTotalRow(); i++) {
        if (dtsObj.getCellData(i, "CHECK") == "T") {
            arrPar[p] = dtsObj.getCellData(i, "ISU_ABBRV2");
            p++;
        }
    }
    return $c.elw.fn_getArrIsuNmInfo(arrPar);
};
scwin.fn_setValueKey = function(dtsObj) {
    scwin.pValue = "";
    scwin.pfirstValue = "";
    var tmpValue = "";
    scwin.fn_sTimer();
    dts_BzProcsNo.removeAll();
    dts_BzProcsNo.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=ELW_WRTRPT_PRINT_HIST_OUT";
    dts_BzProcsNo.reset();
    for (var i = 1; i <= dtsObj.getTotalRow(); i++) {
        if (dtsObj.getCellData(i, "CHECK") == "T") {
            scwin.pfirstValue = dtsObj.getCellData(i, "BZ_PROCS_NO");
            dts_BzProcsNo.insertRow();
            dts_BzProcsNo.setCellData(dts_BzProcsNo.getRowPosition(), "EMP_NO", js_emp_no);
            dts_BzProcsNo.setCellData(dts_BzProcsNo.getRowPosition(), "DATA_CREAT_DDTM", scwin.gCreatDdtm);
            dts_BzProcsNo.setCellData(dts_BzProcsNo.getRowPosition(), "BZ_PROCS_NO", scwin.pfirstValue);
            dts_BzProcsNo.setCellData(dts_BzProcsNo.getRowPosition(), "WRTRPT_TP_CD", $c.stf.getObjectValue(cmb_REPORT_CD));
            if (tmpValue != scwin.pfirstValue.substring(0, 8)) {
                tmpValue = scwin.pfirstValue.substring(0, 8);
                if (i == 1) {
                    scwin.pValue = scwin.pfirstValue;
                } else {
                    scwin.pValue = scwin.pfirstValue + "," + scwin.pValue;
                }
            } else {
                scwin.pValue = dtsObj.getCellData(i, "BZ_PROCS_NO").substring(8, 14) + "," + scwin.pValue;
            }
        }
    }
    trs_Save.Action = "/ElwListedReceive.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02 + "&method=saveElwWrtrptPrint";
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_BzProcsNo)";
    trs_Save.Post();
};
scwin.fn_print = function() {
    var dtsObj;
    if (MaxTab_01.getSelectedTabIndex() == 1) {
        dtsObj = dts_List_1;
    } else if (MaxTab_01.getSelectedTabIndex() == 2) {
        dtsObj = dts_List_2;
    }
    scwin.fn_setValueKey(dtsObj);
    if (scwin.pValue == "") {
        $c.win.alert("[종목]을 선택하세요.");
        return;
    }
    var vReportCd = $c.stf.getObjectValue(cmb_REPORT_CD);
    scwin.fn_setComNm($c.stf.getObjectValue(cmb_ISUR_CD));
    if (vReportCd == "1") {
        var arrIsuStr = scwin.fn_getIsuNmInfo(dtsObj);
        scwin.fn_print_1(arrIsuStr);
    } else if (vReportCd == "2") {
        scwin.fn_print_2();
    } else if (vReportCd == "3") {
        scwin.fn_print_3();
    } else if (vReportCd == "4") {
        var arrIsuStr = scwin.fn_getIsuNmInfo(dtsObj);
        scwin.fn_print_4(arrIsuStr);
    } else if (vReportCd == "5") {
        scwin.fn_print_5();
    }
};



/*var gIndex = 0;
function cutByteLen1(str, start, maxByte) {
    var b, i;

	for (b=i=0;c=str.charCodeAt(i);) {
		b += c>>7 ? 2:1;
		if(b > maxByte)
			break;

		i++;
	}
	gIndex = i;
	return str.substring(start, i);
}*/

scwin.fn_print_1 = function(arrIsuStr) {
    if (MaxTab_01.getSelectedTabIndex() == 2 && $c.stf.getObjectValue(edt_INVSTG_BILL_DD) == "") {
        $c.win.alert("[심사청구일]를 입력하세요.");
        edt_INVSTG_BILL_DD.focus();
        return;
    }
    scwin.fn_read_sync();
    $c.pre_newlisting.fn_corp_read_sync();
    var url = "/ElwListedReceive.do?method=reportElwInvstgStdTable&inputMessageId=ELW_RESULT_REPORT_SEARCH_OUT";
    url += "&REPORT_KND=" + MaxTab_01.getSelectedTabIndex();
    url += "&BZ_PROCS_NO=" + scwin.pfirstValue;
    url += "&EMP_NO=" + js_emp_no;
    url += "&DATA_CREAT_DDTM=" + scwin.gCreatDdtm;
    url += "&INVSTG_BILL_DD=" + $c.stf.getObjectValue(edt_INVSTG_BILL_DD);
    dts_Report_1_01.DataID = encodeURI(url);
    dts_Report_1_01.Reset();
    var vCtnt;
    var pdf_rptname = "";
    var dataSumArr;
    if (MaxTab_01.getSelectedTabIndex() == 1) {
        scwin.rptHeader = scwin.gComNm + " 주식워런트증권";
        pdf_rptname = "RLDSTF00013";
        vCtnt = scwin.gComNm + "이 제출한 " + scwin.gComNm + " 주식워런트증권 " + arrIsuStr[0].ISUR_STR + "의 주식워런트증권 총 " + arrIsuStr[0].ISUR_CNT + "종목에 대한 상장예비심사청구서 및 " + "동 첨부서류를 심사한 결과 유가증권시장상장규정 제140조의 신규상장심사요건중 제140조제2항제4호(공모), 제5호(발행총액) 및 제6호(잔존권리행사기간)를 제외하고 모두 충족하고 있음.";

        //vCtnt	= 	cutByteLen1(vCtnt, 0, 110) + "<br/>" + cutByteLen1(vCtnt, gIndex, 116*2) + "<br/>" +  cutByteLen1(vCtnt, gIndex, 116*3);
        //gIndex = 0;
        dataSumArr = ["ISU_TOTAMT_SUM:ISU_TOTAMT_ORI:FormatTofixed3"];
    } else if (MaxTab_01.getSelectedTabIndex() == 2) {
        scwin.rptHeader = scwin.gComNm + " 주식워런트증권";
        pdf_rptname = "RLDSTF00021";
        vCtnt = scwin.gComNm + "이 제출한 " + scwin.gComNm + " 주식워런트증권 " + arrIsuStr[0].ISUR_STR + "의 주식워런트증권 총 " + arrIsuStr[0].ISUR_CNT + "종목에 대한 추가상장예비심사청구서 및 " + "동 첨부서류를 심사한 결과, 추가상장심사요건중 유가증권시장상장규정 제140조제2항제3호(기초자산) 및 제4호(공모), 141조제2항제2호 (추가발행총액) 및 제3호(잔존만기)를 제외하고 모두 충족하고 있음.";
        dataSumArr = ["FST_ISU_TOT_AMT_SUM:FST_ISU_TOTAMT_ORI:FormatTofixed3", "EXIST_ISU_TOT_AMT_SUM:EXIST_ISU_TOTAMT_ORI:FormatTofixed3", "ADD_ISU_TOTAMT_SUM:ADD_ISU_TOTAMT_ORI:FormatTofixed3", "ACC_ISU_TOTAMT_SUM:ACC_ISU_TOTAMT_ORI:FormatTofixed3"];
    }


    /* 해당 순서가 바뀌면 절대 안됨 */
    var userParam = [{
        uid: "nvl",
        unm: "Y"
    }, {
        uid: "print_time",
        unm: $c.ut.cGetToday("yyyy-mm-dd")
    }, {
        uid: "HEADER",
        unm: scwin.rptHeader
    }, {
        uid: "CTNT",
        unm: vCtnt
    }, {
        uid: "totalPageYn",
        unm: "Y"
    }];


    //set  dts_CorpReport(발행인 개황)
    var dataFormatArr = ["OTC_DRV_BZ_CONFRM_DD:FormatDateEx", "QTR_TOT_ASST_AMT:FormatNumberEx", "HALF_TOT_ASST_AMT:FormatNumberEx", "BIZ_TOT_ASST_AMT:FormatNumberEx", "QTR_TOT_CAP:FormatNumberEx", "HALF_TOT_CAP:FormatNumberEx", "BIZ_TOT_CAP:FormatNumberEx", "QTR_CAP:FormatNumberEx", "HALF_CAP:FormatNumberEx", "BIZ_CAP:FormatNumberEx", "QTR_BZ_PROFT_AMT:FormatNumberEx", "HALF_BZ_PROFT_AMT:FormatNumberEx", "BIZ_BZ_PROFT_AMT:FormatNumberEx", "QTR_NETINCM_AMT:FormatNumberEx", "HALF_NETINCM_AMT:FormatNumberEx", "BIZ_NETINCM_AMT:FormatNumberEx"];
    var jsonData1 = $c.rpt.fn_make_dtsToJson1_wdf(dts_CorpReport, dataFormatArr);


    //set dts_Report (주식워런트증권 내역)
    dataFormatArr = ["ISU_TOTAMT:FormatTofixed3", "ISU_PRC:FormatNumberEx", "EXP_DD:FormatDateEx"];
    //alert(dts_Report.Text);
    var rtnArray = $c.rpt.fn_make_dtsToJson1_wdf_wsum(dts_Report, dataFormatArr, dataSumArr, scwin.userParam);
    var jsonData2 = rtnArray[0];
    scwin.userParam = rtnArray[1];


    //set  dts_Report_1_01 (상장심사기준 대비표)
    dataFormatArr = ["EXP_DD_1:FormatDateEx", "EXP_DD_2:FormatDateEx"];
    var jsonData3 = $c.rpt.fn_make_dtsToJson1_wdf(dts_Report_1_01, dataFormatArr);
    scwin.userParam.push({
        uid: "jsonData1",
        unm: jsonData1
    });
    scwin.userParam.push({
        uid: "jsonData2",
        unm: jsonData2
    });
    scwin.userParam.push({
        uid: "jsonData3",
        unm: jsonData3
    });

    //PDF Convert
    $c.rpt.fn_open_report_pdf(pdf_rptname, scwin.userParam);
};
scwin.fn_print_2 = function() {
    if ($c.stf.getObjectValue(edt_INVSTG_BILL_DD) == "") {
        $c.win.alert("[심사청구일]를 입력하세요.");
        edt_INVSTG_BILL_DD.focus();
        return;
    }
    var vCtnt;
    var pdf_rptname = "";
    var dataSumArr;
    if (MaxTab_01.getSelectedTabIndex() == 1) {
        scwin.rptHeader = scwin.gComNm + " 주식워런트증권";
        pdf_rptname = "RLDSTF00014";
        vCtnt = "상기 신청인이 상장예비심사를 청구한 주식워런트증권을 심사한 결과 " + "상장예비심사청구일(" + scwin.prnDtFormat($c.stf.getObjectValue(edt_INVSTG_BILL_DD)) + ") 현재 유가증권시<br/>장상장규정(이하 '상장규정'이라 한다) 제140조의 " + "신규상장심사요건중 제140조제2항제4호(공모), 제5호(발행총액) 및 <br/>제6호(잔존권리행사기간)를 제외하고 모두 충족하고 있음.";
        dataSumArr = ["ISU_TOTAMT_SUM:ISU_TOTAMT_ORI:FormatTofixed3"];
    } else if (MaxTab_01.getSelectedTabIndex() == 2) {
        scwin.rptHeader = scwin.gComNm + " 주식워런트증권";
        pdf_rptname = "RLDSTF00022";
        vCtnt = "상기 신청인이 추가상장예비심사를 청구한 주식워런트증권을 심사한 결과 " + "추가상장예비심사청구일(" + scwin.prnDtFormat($c.stf.getObjectValue(edt_INVSTG_BILL_DD)) + ") 현재 추<br/>가상장심사요건중 유가증권시장상장규정 제140조제2항제3호(기초자산) 및 " + "제4호(공모), 제141조제2항제2호(추가발<br/>행총액) 및 제3호(잔존만기)를 제외하고 모두 충족하고 있음.";
        dataSumArr = ["FST_ISU_TOT_AMT_SUM:FST_ISU_TOTAMT_ORI:FormatTofixed3", "EXIST_ISU_TOT_AMT_SUM:EXIST_ISU_TOTAMT_ORI:FormatTofixed3", "ADD_ISU_TOTAMT_SUM:ADD_ISU_TOTAMT_ORI:FormatTofixed3", "ACC_ISU_TOTAMT_SUM:ACC_ISU_TOTAMT_ORI:FormatTofixed3"];
    }
    scwin.fn_read_sync();
    $c.pre_newlisting.fn_corp_read_sync();
    var userParam = [{
        uid: "nvl",
        unm: "Y"
    }, {
        uid: "print_time",
        unm: $c.ut.cGetToday("yyyy-mm-dd")
    }, {
        uid: "HEADER",
        unm: scwin.rptHeader
    }, {
        uid: "CTNT",
        unm: vCtnt
    }, {
        uid: "totalPageYn",
        unm: "Y"
    }];

    //set  dts_CorpReport(신규상장 신청인)
    var dataFormatArr = ["ACNTCLS_YYMM:FormatDateExYYMM", "BAS_DD:FormatDateEx"];
    var jsonData1 = $c.rpt.fn_make_dtsToJson1_wdf(dts_CorpReport, dataFormatArr);

    // set dts_Report (주식워런트증권)
    dataFormatArr = ["ISU_TOTAMT:FormatTofixed3", "ISU_PRC:FormatNumberEx", "EXP_DD:FormatDateEx"];
    var rtnArray = $c.rpt.fn_make_dtsToJson1_wdf_wsum(dts_Report, dataFormatArr, dataSumArr, scwin.userParam);
    var jsonData2 = rtnArray[0];
    scwin.userParam = rtnArray[1];
    scwin.userParam.push({
        uid: "jsonData1",
        unm: jsonData1
    });
    scwin.userParam.push({
        uid: "jsonData2",
        unm: jsonData2
    });


    //PDF Convert
    $c.rpt.fn_open_report_pdf(pdf_rptname, scwin.userParam);
};
scwin.fn_print_3 = function() {
    var pdf_rptname = "";
    if (MaxTab_01.getSelectedTabIndex() == 1) {
        scwin.rptHeader = scwin.gComNm + " 주식워런트증권 상장예비심사청구 내역";
        pdf_rptname = "RLDSTF00015";
    } else if (MaxTab_01.getSelectedTabIndex() == 2) {
        scwin.rptHeader = scwin.gComNm + " 주식워런트증권 추가상장예비심사청구 내역";
        pdf_rptname = "RLDSTF00023";
    }
    scwin.vCond = "&LIST_DD=";
    scwin.fn_read_sync();
    var dataFormatArr = ["EXP_DD_1:FormatDateEx", "EXP_DD_2:FormatDateEx", "EXER_STRT_DD_1:FormatDateEx", "EXER_STRT_DD_2:FormatDateEx", "EXER_END_DD_1:FormatDateEx", "EXER_END_DD_2:FormatDateEx", "ELW_LSTTRD_DD_1:FormatDateEx", "ELW_LSTTRD_DD_2:FormatDateEx", "ELW_PAY_DD_1:FormatDateEx", "ELW_PAY_DD_2:FormatDateEx"];
    var jsonData = $c.rpt.fn_make_dtsToJson1_wdf(dts_Report, dataFormatArr);
    var userParam = [{
        uid: "print_time",
        unm: $c.ut.cGetToday("yyyy-mm-dd")
    }, {
        uid: "HEADER",
        unm: scwin.rptHeader
    }, {
        uid: "jsonData",
        unm: jsonData
    }, {
        uid: "totalPageYn",
        unm: "Y"
    }];


    //PDF Convert
    $c.rpt.fn_open_report_pdf(pdf_rptname, scwin.userParam);
};
scwin.fn_print_4 = function(arrIsuStr) {
    if ($c.stf.getObjectValue(edt_INVSTG_BILL_DD) == "") {
        $c.win.alert("[심사청구일]를 입력하세요.");
        edt_INVSTG_BILL_DD.focus();
        return;
    }
    if ($c.stf.getObjectValue(edt_INVSTG_NOTI_DD) == "") {
        $c.win.alert("[심사통지일]를 입력하세요.");
        edt_INVSTG_NOTI_DD.focus();
        return;
    }
    var vCtnt_1 = "";
    var vCtnt_2 = "";
    var pdf_rptname = "";
    if (MaxTab_01.getSelectedTabIndex() == 1) {
        scwin.rptHeader = scwin.gComNm + " 주식워런트증권";
        pdf_rptname = "RLDSTF00017";
