scwin.prnDtFormat = function(dt) {
    return "'" + dt.substring(2, 4) + "." + dt.substring(4, 6) + "." + dt.substring(6);
};
scwin.fn_list_sync = function() {
    if (scwin.lodingYn != 'Y') return;
    if (cmb_ISUR_CD.getSelectedIndex() == 0) {
        $c.win.alert("[발행회사]를 선택하세요.");
        cmb_ISUR_CD.focus();
        return;
    }
    var urlcond = '';
    urlcond += "&ISUR_CD=" + $c.stf.getObjectValue(cmb_ISUR_CD);
    urlcond += "&REQ_SDATE=" + $c.stf.getObjectValue(edt_ReqSDate);
    urlcond += "&REQ_EDATE=" + $c.stf.getObjectValue(edt_ReqEDate);
    urlcond += "&LIST_BZ_TP_CD=" + scwin.fn_getListBzTpCd();
    urlcond += "&LIST_PROCS_STAT_CD=" + $c.stf.getObjectValue(cmb_LIST_PROCS_STAT_CD);
    if (MaxTab_01.getSelectedTabIndex() == 1) {
        var url = "/ElwListedReceive.do?method=listElwReceiptReport&inputMessageId=ELW_RECV_LSTRCV_INOUT";
        url += urlcond;
        url += "&SCREN_ID=" + scwin.vScrenID;
        url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        //alert("vListMdCd :"+vListMdCd);
        dts_List_1.DataID = encodeURI(url);
        dts_List_1.Reset();
        $c.cm.setColumnProp(grd_List_1, 'CHECK', 'HeadCheck', false);
        $c.cm.ShowWin(grd_List_1);
    } else if (MaxTab_01.getSelectedTabIndex() == 2) {
        var url = "/ElwListedReceive.do?method=listElwAddReceiptReport&inputMessageId=ELW_RECV_LSTRCV_INOUT";
        url += urlcond;
        //alert("vListMdCd :"+vListMdCd);
        url += "&SCREN_ID=" + scwin.vScrenID;
        url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        dts_List_2.DataID = encodeURI(url);
        dts_List_2.Reset();
        $c.cm.setColumnProp(grd_List_2, 'CHECK', 'HeadCheck', false);
        $c.cm.ShowWin(grd_List_2);
    }
};
scwin.fn_setBzProcsNo = function(obj, dtsObj) {
    scwin.clickBzProcsNo = dtsObj.getCellData(eval(obj), "BZ_PROCS_NO");
};
scwin.fn_OpenDetail = function(row, dtsObj) {
    scwin.fn_setBzProcsNo(row, dtsObj);
    var vbzTpCd = dtsObj.getCellData(row, "LIST_BZ_TP_CD");
    $c.elw.fn_OpenDetailRecv(vbzTpCd);
};


