    dts_Print.insertRow();
    scwin.userParam = [{
        uid: "HEADER",
        unm: scwin.rptHeader
    }, {
        uid: "CTNT_1",
        unm: vCtnt_1
    }, {
        uid: "CTNT_2",
        unm: vCtnt_2
    }];
    scwin.fn_read_sync();
    scwin.testDateSet = rex_gfGetGauceCsvStr(dts_Print, dts_Report);
    //alert('[testDateSet]'+testDateSet);
    $c.rpt.fn_open_report(scwin.testDateSet, scwin.rex_rptname, scwin.userParam);
};
scwin.fn_print_5_old = function() {
    if ($c.stf.getObjectValue(edt_LIST_DD) == "") {
        $c.win.alert("[상장일지정]를 입력하세요.");
        edt_LIST_DD.focus();
        return;
    }
    if (MaxTab_01.getSelectedTabIndex() == 1) {
        scwin.rptHeader = scwin.gComNm + " 주식워런트증권 신규상장 내역";
        scwin.rex_rptname = "RLDSTF00016";
    } else if (MaxTab_01.getSelectedTabIndex() == 2) {
        scwin.rptHeader = scwin.gComNm + " 주식워런트증권 추가상장 내역";
        scwin.rex_rptname = "RLDSTF00024";
    }
    scwin.userParam = [{
        uid: "HEADER",
        unm: scwin.rptHeader
    }];
    scwin.vCond = "&LIST_DD=" + $c.stf.getObjectValue(edt_LIST_DD);
    scwin.fn_read_sync();
    scwin.testDateSet = rex_gfGetGauceCsvStr(dts_Report);
    //alert('[testDateSet]'+testDateSet);
    $c.rpt.fn_open_report(scwin.testDateSet, scwin.rex_rptname, scwin.userParam);
};
scwin.cmb_ISUR_CD_OnSelChange = function() {
    scwin.fn_list_sync();
};
scwin.cmb_REPORT_CD_OnSelChange = function() {
    edt_INVSTG_BILL_DD.setReadOnly(true);
    edt_INVSTG_BILL_DD.ReadOnlyBackgroundColor = '#b9d4f7';
    edt_INVSTG_NOTI_DD.setReadOnly(true);
    edt_INVSTG_NOTI_DD.ReadOnlyBackgroundColor = '#b9d4f7';
    edt_LIST_DD.setReadOnly(true);
    edt_LIST_DD.ReadOnlyBackgroundColor = '#b9d4f7';
    var vReportCd = $c.stf.getObjectValue(cmb_REPORT_CD);
    if (vReportCd == "2") {
        edt_INVSTG_BILL_DD.setReadOnly(false);
        edt_INVSTG_BILL_DD.ReadOnlyBackgroundColor = '#ffffff';
    } else if (vReportCd == "4") {
        edt_INVSTG_BILL_DD.setReadOnly(false);
        edt_INVSTG_BILL_DD.ReadOnlyBackgroundColor = '#ffffff';
        edt_INVSTG_NOTI_DD.setReadOnly(false);
        edt_INVSTG_NOTI_DD.ReadOnlyBackgroundColor = '#ffffff';
    } else if (vReportCd == "5") {
        edt_LIST_DD.setReadOnly(false);
        edt_LIST_DD.ReadOnlyBackgroundColor = '#ffffff';
    }
    if (MaxTab_01.getSelectedTabIndex() == 2 && vReportCd == "1") {
        edt_INVSTG_BILL_DD.setReadOnly(false);
        edt_INVSTG_BILL_DD.ReadOnlyBackgroundColor = '#ffffff';
    }
    scwin.fn_list_sync();
};
scwin.MaxTab_01_OnSelChanged = function(nIndex) {
    scwin.fn_list_sync();
    var vReportCd = $c.stf.getObjectValue(cmb_REPORT_CD);
    if (vReportCd == "1") {
        if (MaxTab_01.getSelectedTabIndex() == 2) {
            edt_INVSTG_BILL_DD.setReadOnly(false);
            edt_INVSTG_BILL_DD.ReadOnlyBackgroundColor = '#ffffff';
        } else {
            edt_INVSTG_BILL_DD.setReadOnly(true);
            edt_INVSTG_BILL_DD.ReadOnlyBackgroundColor = '#b9d4f7';
        }
    }
};
