scwin.btn_Print_onclick = function() {
    var vCheckLmt = 0;
    if (MaxTab_01.getSelectedTabIndex() == 1) {
        for (var i = 1; i <= dts_List_1.getTotalRow(); i++) {
            if (dts_List_1.getCellData(i, "CHECK") == "T") {
                vCheckLmt = vCheckLmt + 1;
            }
        }
        if (vCheckLmt > 1000) {
            $c.win.alert("인쇄가능 데이터는 1,000건으로 제한 됩니다.(현재 " + vCheckLmt + " 건 선택)");
            return false;
        }
    } else if (MaxTab_01.getSelectedTabIndex() == 2) {
        for (var i = 1; i <= dts_List_2.getTotalRow(); i++) {
            if (dts_List_2.getCellData(i, "CHECK") == "T") {
                vCheckLmt = vCheckLmt + 1;
            }
        }
        if (vCheckLmt > 1000) {
            $c.win.alert("인쇄가능 데이터는 1,000건으로 제한 됩니다.(현재 " + vCheckLmt + " 건 선택 )");
            return false;
        }
    }
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_05);
    scwin.fn_print();
};
